package com.example.incidentapp.worker;
import android.content.Context; import androidx.annotation.NonNull; import androidx.work.*; import com.example.incidentapp.local.AppDatabase; import com.example.incidentapp.local.entity.SolicitudPendienteEntity; import com.example.incidentapp.model.RegistroIncidenteResponse; import com.example.incidentapp.repository.IncidenteRepository; import com.example.incidentapp.session.SessionManager; import com.example.incidentapp.util.MultipartUtils; import java.io.File; import java.util.*; import okhttp3.MultipartBody; import retrofit2.Response;
public class SincronizarPendientesWorker extends Worker { public SincronizarPendientesWorker(@NonNull Context c,@NonNull WorkerParameters p){super(c,p);} @NonNull @Override public Result doWork(){SessionManager.init(getApplicationContext());AppDatabase.init(getApplicationContext());if(!SessionManager.getInstance().haySesion())return Result.success();try{List<SolicitudPendienteEntity> items=AppDatabase.get().solicitudPendienteDao().listar(SessionManager.getInstance().getIdUsuario());IncidenteRepository repo=new IncidenteRepository();for(SolicitudPendienteEntity e:items){List<MultipartBody.Part> fotos=new ArrayList<>();if(e.foto1Path!=null)fotos.add(MultipartUtils.crearParteFotoDesdeArchivo(new File(e.foto1Path)));if(e.foto2Path!=null)fotos.add(MultipartUtils.crearParteFotoDesdeArchivo(new File(e.foto2Path)));Response<RegistroIncidenteResponse> r=repo.registrarIncidente(e.titulo,e.descripcion,e.categoria,e.prioridad,e.idSucursal,e.idActivo,fotos).execute();if(r.isSuccessful()){AppDatabase.get().solicitudPendienteDao().eliminar(e);if(e.foto1Path!=null)new File(e.foto1Path).delete();if(e.foto2Path!=null)new File(e.foto2Path).delete();}else return Result.retry();}return Result.success();}catch(Exception ex){return Result.retry();}} }
